import json
from pathlib import Path


TASK_ROOT = Path(__file__).resolve().parent
REPORT = TASK_ROOT / "outputs" / "public_reproduction_report.json"
MODEL_FIXTURE = TASK_ROOT / "fixtures" / "regional_event.nc"
STATION_FIXTURE = TASK_ROOT / "fixtures" / "station_observations.csv"
CHECKPOINT = TASK_ROOT / "outputs" / "regional_event_checkpoint.nc"


def write_report(payload: dict[str, object], code: int) -> int:
    REPORT.parent.mkdir(parents=True, exist_ok=True)
    text = json.dumps(payload, indent=2, sort_keys=True) + "\n"
    REPORT.write_text(text, encoding="utf-8")
    print(text, end="")
    return code


def main() -> int:
    try:
        from workflow.public_workflow import run_public_case

        result = run_public_case(MODEL_FIXTURE, STATION_FIXTURE, CHECKPOINT)
    except Exception as exc:  # noqa: BLE001 - classify infrastructure separately.
        return write_report(
            {
                "schema_version": "1.0",
                "status": "runner_failure",
                "error_type": type(exc).__name__,
                "error": str(exc),
            },
            2,
        )

    scientific_success = bool(
        result["finite"] and result["workflow_consistent"]
    )
    return write_report(
        {
            "schema_version": "1.0",
            "status": "post_fix_success" if scientific_success else "pre_fix_expected_failure",
            "observation": {
                "finite": result["finite"],
                "shape": result["shape"],
                "regional_validation_consistent": result[
                    "workflow_consistent"
                ],
            },
        },
        0 if scientific_success else 1,
    )


if __name__ == "__main__":
    raise SystemExit(main())

